import codecs
for name in ('strict', 'ignore', 'replace', 'xmlcharrefreplace', 'backslashreplace', 'namereplace', 'surrogatepass', 'surrogateescape'):
    handler = codecs.lookup_error(name)
    for operation in (lambda: handler(), lambda: handler(None, None), lambda: handler(object=None), lambda: handler(None)):
        try:
            operation()
        except TypeError as error:
            print(name, type(error).__name__, error.args, error.__context__, getattr(error, '__notes__', None), error.__traceback__ is not None)
        else:
            raise AssertionError('missing rejection')
for name, exception, field, missing in (('ignore', UnicodeEncodeError, 'object', True), ('replace', UnicodeDecodeError, 'object', False), ('surrogatepass', UnicodeEncodeError, 'encoding', True), ('surrogatepass', UnicodeDecodeError, 'encoding', False)):
    original = exception('utf-8', b'x' if exception is UnicodeDecodeError else 'x', 0, 1, 'reason')
    if missing:
        delattr(original, field)
    else:
        setattr(original, field, None)
    try:
        codecs.lookup_error(name)(original)
    except TypeError as error:
        print(name, field, type(error).__name__, error.args, error is original, error.__traceback__ is not None)
    else:
        raise AssertionError('missing field rejection')
print(input())
